import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.BXzK3EA4.js";const r="/assets/188_27d06966-3763-448a-a8ac-b53de8c39673.Cae_JBBe.png",n="/assets/185_blobid5.3hUr403-.png",g=JSON.parse('{"title":"物理服务器打开VNC窗口","description":"","frontmatter":{"title":"物理服务器打开VNC窗口"},"headers":[],"relativePath":"ops-knowledge-base/dedicated-server/open-vnc-window.md","filePath":"ops-knowledge-base/dedicated-server/open-vnc-window.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/dedicated-server/open-vnc-window.md"};function s(d,e,c,h,p,_){return t(),o("div",null,[...e[0]||(e[0]=[l('<h2 id="一、功能介绍" tabindex="-1">一、功能介绍 <a class="header-anchor" href="#一、功能介绍" aria-label="Permalink to &quot;一、功能介绍&quot;">​</a></h2><p>VNC是一种为用户提供的通过 Web 浏览器远程连接服务器的方式。当您未安装远程登录客户端，或客户端远程登录出现问题时，可通过 VNC 连接到服务器，实时观察服务器状态，并使用服务器账户开展基本的服务器管理操作，如执行命令、查看系统日志等。</p><h2 id="二、操作入口" tabindex="-1">二、操作入口 <a class="header-anchor" href="#二、操作入口" aria-label="Permalink to &quot;二、操作入口&quot;">​</a></h2><ol><li>登录平台，进入客户<strong>中心</strong>，下方**“我的订单”** 点击 **“物理服务器”**。或者在 **“产品管理”** 点击 **“物理服务器”**，根据机器所在地区和状态筛选。</li><li>在产品列表中，找到目标服务器，点击进入 **“产品详情”** 页面。</li><li>在 “服务器信息” 标签页下，找到并点击 **“VNC”** 按钮，即可启动 VNC 连接，进入 VNC 操作界面。</li></ol><p><img src="'+r+'" alt=""></p><h2 id="三、vnc-界面功能" tabindex="-1">三、VNC 界面功能 <a class="header-anchor" href="#三、vnc-界面功能" aria-label="Permalink to &quot;三、VNC 界面功能&quot;">​</a></h2><h3 id="一-顶部操作栏" tabindex="-1">（一）顶部操作栏 <a class="header-anchor" href="#一-顶部操作栏" aria-label="Permalink to &quot;（一）顶部操作栏&quot;">​</a></h3><ul><li><strong>强制刷新 vnc</strong>：当 VNC 画面显示异常或卡顿，点击该按钮可强制刷新画面，恢复正常显示。</li><li><strong>开机 / 关机 / 重启</strong>：可直接在 VNC 界面对服务器执行开机、关机、重启操作，方便快捷地管理服务器电源状态。</li></ul><h3 id="二-快捷操作功能" tabindex="-1">（二）快捷操作功能 <a class="header-anchor" href="#二-快捷操作功能" aria-label="Permalink to &quot;（二）快捷操作功能&quot;">​</a></h3><ul><li><strong>剪切板</strong>：若您有需要输入到服务器控制台的命令或密码等文本，可先将其复制到本地剪切板，然后在 VNC 界面点击 “剪切板”，在弹出的输入框中粘贴文本，点击 “确定”，即可将文本发送到服务器控制台，无需手动输入，提升操作效率。</li><li><strong>粘贴密码</strong>：点击该功能，系统会自动将服务器后台的密码粘贴到控制台输入区域，方便您快速进行登录等需要密码的操作。</li><li><strong>Send CtrlAltDel</strong>：模拟键盘的 “Ctrl + Alt + Del” 组合键操作，在 Windows 系统场景下，可用于触发系统登录界面。</li></ul><p><img src="'+n+'" alt=""></p><h2 id="四、注意事项" tabindex="-1">四、注意事项 <a class="header-anchor" href="#四、注意事项" aria-label="Permalink to &quot;四、注意事项&quot;">​</a></h2><ol><li>通过 VNC 进行服务器管理时，操作具有与本地操作相同的权限，请注意谨慎操作，避免误操作导致服务器故障或数据丢失。</li><li>若 VNC 无法成功连接或黑屏，可尝试在后台“重置BMC”、重启服务器或联系平台技术支持。</li></ol>',13)])])}const C=a(i,[["render",s]]);export{g as __pageData,C as default};
